namespace sv_8cbf76221b6c46128e7e6ecc0e9906aa.Services;

public class WarehouseState
{
    private string _currentWarehouseId = "WH-001";
    private string _currentWarehouseName = "Warehouse A";

    public string CurrentWarehouseId => _currentWarehouseId;
    public string CurrentWarehouseName => _currentWarehouseName;

    public event Action? OnChange;

    public static IReadOnlyList<(string Id, string Name)> AvailableWarehouses { get; } =
    [
        ("WH-001", "Warehouse A"),
        ("WH-002", "Warehouse B"),
        ("WH-003", "Warehouse C"),
        ("WH-004", "Warehouse D"),
    ];

    public void SetWarehouse(string warehouseId, string warehouseName)
    {
        if (_currentWarehouseId == warehouseId)
            return;

        _currentWarehouseId = warehouseId;
        _currentWarehouseName = warehouseName;
        OnChange?.Invoke();
    }
}

namespace sv_8cbf76221b6c46128e7e6ecc0e9906aa.Services;

public class InventoryAlertService
{
    private readonly Random _random = new();

    public int LastKnownCount { get; private set; }

    public event Action? OnAlertCountChanged;

    /// <summary>
    /// Simulates a database query returning low-stock item count for a warehouse.
    /// </summary>
    public Task<int> GetLowStockCountAsync(string warehouseId)
    {
        var count = _random.Next(0, 16);
        return Task.FromResult(count);
    }

    /// <summary>
    /// Updates the cached count and notifies all subscribers.
    /// Called by the polling component when new data arrives.
    /// </summary>
    public void UpdateAlertCount(int newCount)
    {
        LastKnownCount = newCount;
        OnAlertCountChanged?.Invoke();
    }
}

