@rendermode InteractiveServer
@inject WarehouseState WarehouseState
@implements IDisposable

<div class="d-flex align-items-center">
    <label class="me-2 text-nowrap fw-semibold">Warehouse:</label>
    <select class="form-select form-select-sm" style="width: auto;"
            value="@WarehouseState.CurrentWarehouseId"
            @onchange="OnWarehouseChanged">
        @foreach (var wh in WarehouseState.AvailableWarehouses)
        {
            <option value="@wh.Id">@wh.Name</option>
        }
    </select>
</div>

@code {
    protected override void OnInitialized()
    {
        WarehouseState.OnChange += OnStateChanged;
    }

    private void OnWarehouseChanged(ChangeEventArgs e)
    {
        var selectedId = e.Value?.ToString() ?? "";
        var warehouse = WarehouseState.AvailableWarehouses
            .FirstOrDefault(w => w.Id == selectedId);

        if (!string.IsNullOrEmpty(warehouse.Id))
        {
            WarehouseState.SetWarehouse(warehouse.Id, warehouse.Name);
        }
    }

    private void OnStateChanged() => InvokeAsync(StateHasChanged);

    public void Dispose()
    {
        WarehouseState.OnChange -= OnStateChanged;
    }
}

@rendermode InteractiveServer
